            n = float('Inf')
        if qid == -1:
            qid = self.last_query_id

        # Append DISCARD message to the output queue
        discard_message = {"discard": {"n": n, "qid": qid}}
        self.output_queue.append(discard_message)

        # Handle response with dehydration and hydration hooks
