def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to even.

    :param n: The number to round.
    :return: The rounded integer.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be an integer or float.")

    if n % 1 == 0:
        return int(n)

    integer_part = int(n)
    decimal_part = n % 1

    if decimal_part == 0.5:
        return integer_part + (1 if integer_part % 2 == 0 else 0)
    else:
        return round(n)

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding halfway cases away from zero.

    :param n: The number to round.
    :return: The rounded number.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be an int or float.")

    if n >= 0:
        return int(n + 0.5) if n - int(n) >= 0.5 else int(n)
    else:
        return int(n - 0.5) if n - int(n) <= -0.5 else int(n)

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, adhering to the "round half to even" rule.

    :param n: The number to round.
    :return: The rounded number.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    if n >= 0:
        return int(n + 0.5) - int(n % 1 == 0.5)
    else:
        return int(n - 0.5) + int(n % -1 == -0.5)

def round_half_to_even(n):
    """
    Round half to even

    :param n: The number to round.
    :return: The rounded number
    """
    if n % 1 == 0:
        return int(n)
    elif abs(n - round(n)) == 0.5:
        return round(n, 0)
    else:
        return int(round(n))

