    if not all(field[0].endswith('_srid') for field in fields[1:]):
        raise ValueError("All fields must end with '_srid'")

    srid_field = next(field for field in fields if field[0] == 'srid')
    fields = [(field[0], field[1], field[2] if len(field) == 3 else srid_field[2]) for field in fields]

    class Point(fields[0][1], metaclass=PointMeta):
        __init__ = PointBase.__init__
        __repr__ = PointBase.__repr__

        @property
