    def _hashable(key):
        if isinstance(key, tuple):
            return tuple(_hashable(k) for k in key)
        else:
            return hash(key)

    def _cache_info():
        return len(cache), maxsize, len(hit), len(miss)

    cache = OrderedDict()
    AccessOrder = []
    hit = miss = 0

    def get(key, default=None):
        nonlocal hit, miss
        if key not in cache:
            miss += 1
            return default
        else:
            hit += 1
            AccessOrder.remove(key)
            AccessOrder.append(key)
            return cache[key]

    def delete_expired():
        nonlocal cache, AccessOrder
        current_time = timer()
        expired = [k for k in AccessOrder if cache[k][1] + ttl < current_time]
        for k in expired:
            del cache[k]
            AccessOrder.remove(k)

    def decorator(func):
        nonlocal cache, AccessOrder, hit, miss

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = tuple(_hashable(arg) for arg in args) + tuple(_hashable(kw) for kw, val in kwargs.items())
            if maxsize == 0:
                return func(*args, **kwargs)

            delete_expired()

            item = get(key, (func(*args, **kwargs), timer()))
            if len(cache) == maxsize and key not in cache:
                old_key = AccessOrder.pop(0)
                del cache[old_key]

            AccessOrder.append(key)
            cache[key] = item
            return item[0]

        wrapper.cache_info = _cache_info
        wrapper.cache_clear = cache.clear
        return wrapper

    return decorator

