    def __init__(self, value, count=1):
        self.value = value
        self.count = count

class LFUCache:
    def __init__(self, maxsize, typed):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = {}
        self.q = defaultdict(set)
        self.size = 0
        self.min_count = 0

    def _update_count(self, key):
        node = self.cache[key]
        new_count = node.count + 1
        node.count = new_count
        self.q[node.count - 1].remove(key)
        self.q[new_count].add(key)
        if node.count - 1 == self.min_count and not self.q[node.count - 1]:
            self.min_count = new_count

    def get(self, key):
        if key not in self.cache:
            return -1
        node = self.cache[key]
        self._update_count(key)
        return node.value

    def put(self, key, value):
        if key in self.cache:
            node = self.cache[key]
            node.value = value
            self._update_count(key)
        else:
            if self.size == self.maxsize:
                evict_key = self.q[self.min_count].pop()
                del self.cache[evict_key]
                self.size -= 1
            node = Node(value)
            self.cache[key] = node
            self.q[node.count].add(key)
            self.size += 1
            self.min_count = 1

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """

    def decorator(func):
        cache = LFUCache(maxsize, typed)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (func, args, tuple(kwargs.items()), type(args), type(kwargs)) if typed else (func, args, tuple(kwargs.items()))
            value = cache.get(key)
            if value == -1:
                value = func(*args, **kwargs)
                cache.put(key, value)
            return value

        return wrapper

    return decorator

