def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        frequency = defaultdict(int)
        access_count = 0

        def get_key(*args, **kwargs):
            return args if not typed else (type(o) for o in args) + (args, tuple(sorted(kwargs.items())))

        def _put(key, value):
            nonlocal access_count
            access_count += 1
            frequency[key] += 1
            entry = (frequency[key], access_count, value)
            if key in cache:
                heapq.heapreplace(cache[key], entry)
            else:
                cache[key] = [entry]

        def _get(key):
            if key not in cache:
                raise KeyError(key)
           堆队列不支持直接访问或修改元素，因此我们需要遍历堆队列并更新频次和访问次数
            for entry in cache[key]:
                entry[0] += 1
            return heapq.heappop(cache[key])[2]

        def wrapper(*args, **kwargs):
            key = get_key(*args, **kwargs)
            try:
                return _get(key)
            except KeyError:
                value = func(*args, **kwargs)
                _put(key, value)
                if len(cache) > maxsize:
                    oldest = min(cache.keys(), key=lambda k: min(entry[0] for entry in cache[k]))
                    cache.pop(oldest)
                return value

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import defaultdict
    from heapq import heappop, heappush

    class Node:
        def __init__(self, key, value, freq=1):
            self.key = key
            self.value = value
            self.freq = freq

        def increment_freq(self):
            self.freq += 1

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self._cache = dict()
            self._frequencies = defaultdict(list)
            self._min_freq = 0

        def __getitem__(self, key):
            node = self._cache[key]
            node.increment_freq()
            self._frequencies[node.freq - 1].remove(node)
            heappush(self._frequencies[node.freq], node)
            self._min_freq = min(self._min_freq, node.freq)
            return node.value

        def __setitem__(self, key, value):
            if self.typed and not isinstance(key, tuple):
                raise ValueError("If typed is True, key must be a tuple")
            if key in self._cache:
                self.__getitem__(key)
                self._cache[key].value = value
            else:
                if len(self._cache) >= self.maxsize:
                    while not self._frequencies[self._min_freq]:
                        self._min_freq += 1
                    node = heappop(self._frequencies[self._min_freq])
                    del self._cache[node.key]
                new_node = Node(key, value)
                self._cache[key] = new_node
                heappush(self._frequencies[new_node.freq], new_node)
                self._min_freq = min(self._min_freq, new_node.freq)

        def __contains__(self, key):
            return key in self._cache

    def decorator(func):
        cache = LFUCache(maxsize, typed)

        def wrapper(*args, **kwargs):
            key = (func, args, tuple(kwargs.items())) if typed else (func, args)
            if key not in cache:
                cache[key] = func(*args, **kwargs)
            return cache[key]

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import OrderedDict, defaultdict

    class Node:
        def __init__(self, key, value, count=1):
            self.key = key
            self.value = value
            self.count = count

    def decorator(func):
        if maxsize == 0:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        else:
            data = {}
            frequency = defaultdict(OrderedDict)
            min_freq = 1

            def get(key):
                node = data[key]
                del frequency[node.count][key]
                if not frequency[node.count]:
                    del frequency[node.count]
                node.count += 1
                frequency[node.count][key] = node
                nonlocal min_freq
                if min_freq != 1 and min_freq not in frequency:
                    min_freq += 1
                return node.value

            def set_(key, value):
                if key in data:
                    node = data[key]
                    del frequency[node.count][key]
                    if not frequency[node.count]:
                        del frequency[node.count]
                    node.value = value
                    node.count += 1
                    frequency[node.count][key] = node
                else:
                    if len(data) >= maxsize:
                        while min_freq in frequency:
                            oldest_key = next(iter(frequency[min_freq]))
                            del data[oldest_key]
                            del frequency[min_freq][oldest_key]
                    node = Node(key, value)
                    data[key] = node
                    frequency[node.count][key] = node
                    min_freq = 1

            def wrapper(*args, **kwargs):
                key = args if not typed else (type(args), args, type(kwargs), kwargs)
                if key in data:
                    return get(key)
                else:
                    value = func(*args, **kwargs)
                    set_(key, value)
                    return value

        return wrapper

    return decorator

