def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def get_path(level, max_level):
        if level > max_level:
            return "..."
        return f"{level}"

    def get_exception_details(e, level):
        if level > max_level:
            return "..."
        else:
            return f"{e.__class__.__name__}: {e}"

    def get_call_stack_details(tb, level, max_path_level):
        if not tb or level > max_level:
            return ""
        paths = []
        for frame_info in traceback.extract_tb(tb):
            path, line, name, src = frame_info
            if len(paths) >= max_path_level:
                paths.append("...")
                break
            paths.append(f"{path}:{line} - {name}")
        return "\n".join(paths)

    tb = e.__traceback__
    exception_details = get_exception_details(e, 0)
    call_stack_details = get_call_stack_details(tb, 1, max_path_level)

    return f"{exception_details}\n{call_stack_details}"

