    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    return zope_directlyProvidedBy(obj)

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    seen = set()
    minimal = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        can_merge = True
        for base in cls.__bases__:
            if base in seen:
                continue
            seen.add(base)
            if base not in minimal:
                can_merge = False
                break
        if can_merge:
            for base in cls.__bases__:
                if base in seen:
                    continue
                seen.add(base)
                minimal.append(base)
            minimal.append(cls)
    minimal.sort(key=classes.index)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def dfs(cls, seen=None):
        if seen is None:
            seen = set()
        if cls in seen:
            return []
        seen.add(cls)
        return [cls] + sum(dfs(b, seen) for b in cls.__bases__, [])

    bases = [class_ for class_ in classes if not issubclass(class_, object)]
    min_bases = {}

    for cls in bases:
        min_path = dfs(cls)
        min_path_str = '/'.join(map(str, min_path))
        if min_path_str not in min_bases:
            min_bases[min_path_str] = cls

    return list(min_bases.values())

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    if not classes:
        return []

    result = list(classes)
    for cls in classes:
        result = [c for c in result if c not in cls.__bases__]

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        # Add the MRO of the class to the result list
        result.extend(cls.__mro__)
    # Remove duplicates while preserving order
    minimal = []
    for cls in result:
        if cls not in minimal:
            minimal.append(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    classes = list(map(set, classes))  # Convert each list to a set for efficient operations

    # Remove classes that are subclasses of others
    for i, cls1 in enumerate(classes):
        for j, cls2 in enumerate(classes):
            if i != j and cls1.issubset(cls2):
                classes[i] = set()  # Mark this class as to be removed

    # Filter out marked classes and convert the sets back to lists
    minimal = [list(cls) for cls in classes if cls]

    # Sort the minimal list of bases by class name to ensure a consistent order
    minimal.sort(key=lambda x: x[0])

    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""

    attribute_info = {}
    for attr_name in dir(self):
        attribute = getattr(self, attr_name)
        if callable(attribute) or not attribute_name.startswith('__'):
            description = getattr(attribute, '__doc__', None) or f"Description for {attr_name}"
            attribute_info[attr_name] = description

    if all:
        return attribute_info

    return {name: description for name, description in attribute_info.items() if name.startswith('get') or name.startswith('set') or name.startswith('is')}

