import csv

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    raise DeprecationWarning("to_csv is not used. Use lena.output.ToCSV instead.")

    def format_value(value, separator):
        if isinstance(value, (list, tuple)):
            return separator.join(map(str, value))
        return str(value)

    coordinates = self.get_coordinates()
    values = self.get_values()

    if header:
        output = [header]
    else:
        output = []

    for coord, value in zip(coordinates, values):
        coord_str = format_value(coord, separator)
        value_str = format_value(value, separator)
        output.append(f"{coord_str}{separator}{value_str}")

    return "\n".join(output)

def _get_err_indices(self, coord_name):
    """
    Get error indices corresponding to a coordinate.

    Args:
        coord_name: Name of the coordinate for which to get error indices.

    Returns:
        A list of indices corresponding to errors in the specified coordinate.
        If no errors are found, an empty list is returned.
    """
    from .dataarray import DataArray

    if coord_name not in self.coordinates:
        raise ValueError(f"Coordinate '{coord_name}' not found.")

    error_indices = []
    for i, coord_value in enumerate(self.coordinates[coord_name]):
        if isinstance(coord_value, DataArray):
            if coord_value.has_errors():
                error_indices.append(i)
        else:
            raise TypeError("Coordinate values must be DataArray instances.")

    return error_indices

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    for field in self._fields:
        if field.startswith('error'):
            error_type = field.split('_')[-1]
            if error_type not in context['error']:
                context['error'][error_type] = {}
            context['error'][error_type]['index'] = self._fields.index(field)
        else:
            if field not in context['value']:
                context['value'][field] = self._values[field]
            elif error_type := field.replace('error', 'x'):
                context['value'][error_type] = self._values[field]

def _update_context(self, context):
