    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """

    if 'error' not in context:
        context['error'] = {}

    for field, value in self._fields.items():
        if '_error_' in field:
            parts = field.split('_error_')
            axis = parts[0][-1]
            if axis in 'xyz':
