def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if not context.get('value'):
        context['value'] = {}

    if 'error' not in context:
        context['error'] = {}

    fields = self.get_fields()
    for field in fields:
        if 'error_' in field:
            error_field = field.replace('error_', '')
            if error_field not in context['error']:
                context['error'][error_field] = {'index': fields.index(error_field)}

    for key, value in self.get_properties().items():
        if key not in context['value']:
            context['value'][key] = value
        else:
            context['value'][key].update(value)

    return context

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Check for existing error context and append new indices
    if 'error' in context:
        for field in self.fields:
            if 'error_' + field in self.fields:
                error_index = self.fields.index('error_' + field)
                if 'error' not in context:
                    context['error'] = {}
                if error_index not in context['error']:
                    context['error'][error_index] = {}
                context['error'][error_index]['x'] = {'index': error_index}

    # Update context with values of the graph
    for field, values in self.values.items():
        if field not in context['value']:
            context['value'][field] = []
        context['value'][field].extend(values)

    return context

