def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both inputs must be dictionaries")

    if level == 0:
        return {}
    elif level == -1:
        level = None

    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            recursive_diff = difference(d1[key], d2[key], level - 1)
            if recursive_diff:
                result[key] = recursive_diff
        elif d1[key] != d2[key]:
            result[key] = d1[key]

    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}

    if isinstance(d1, dict) and isinstance(d2, dict):
        diff = {}
        for key in d1:
            if key not in d2:
                diff[key] = d1[key]
            else:
                if level > 0:
                    sub_diff = difference(d1[key], d2[key], level - 1)
                    if sub_diff:
                        diff[key] = sub_diff
                elif d1[key] != d2[key]:
                    diff[key] = d1[key]
        return diff
    else:
        return d1 if d1 != d2 else None

def difference(d1, d2, level=-1, depth=0):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return d1

    if level == 0:
        return {}

    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        else:
            diff = difference(value, d2[key], level=level, depth=depth + 1)
            if diff:
                result[key] = diff

    return result

import copy

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return copy.deepcopy(d1)

    result = {}
    for key in d1:
        if key in d2:
            if level == 1 or not isinstance(d1[key], dict):
                if d1[key] != d2[key]:
                    result[key] = d1[key]
            else:
                diff = difference(d1[key], d2[key], level - 1)
                if diff:
                    result[key] = diff
        else:
            result[key] = d1[key]

    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}
    if type(d1) != dict or type(d2) != dict:
        return d1
    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        elif isinstance(value, dict):
            sub_difference = difference(value, d2.get(key, {}), level - 1)
            if sub_difference:
                result[key] = sub_difference
        elif value != d2[key]:
            result[key] = value
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.min_edge or coord >= self.max_edge:
        return
    bin_index = int((coord - self.min_edge) / self.bin_width)
    if bin_index < 0 or bin_index >= len(self.values):
        return
    self.values[bin_index] += weight

import re
from typing import Dict, List, Union

class ValidationError(Exception):
    """Custom exception to hold multiple validation errors."""
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__(self.format_messages())

    def format_messages(self) -> str:
        return ", ".join(f"{k}: {v}" for errors in self.messages for k, v in errors.items())

def _validate_labels(labels: Dict[str, Union[str, List]]) -> None:
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """

    key_regex = re.compile(r'^[a-zA-Z_][0-9a-zA-Z_]*$')
    value_regex = re.compile(r'^[a-zA-Z_][0-9a-zA-Z_]*$')

    errors = []

    for key, value in labels.items():
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str) or not value_regex.match(v):
                    errors.append({repr(v): "expected string or bytes-like object"})
        elif not isinstance(value, str) or not value_regex.match(value):
            errors.append({repr(value): "expected string or bytes-like object"})

        if not isinstance(key, str) or not key_regex.match(key):
            errors.append({repr(key): "Label key does not match the regex"})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    regexes = {
        'key': r'^.+$',
        'value': r'^.+$',
    }

    errors = []

    for key, value in labels.items():
        key_error = None
        value_error = None

        if isinstance(key, list):
            key_error = {"['invalid']": 'expected string or bytes-like object'}
        elif not re.match(regexes['key'], key):
            key_error = {str(key): "Label key does not match the regex"}

        if isinstance(value, list):
            value_error = {str(value): 'expected string or bytes-like object'}
        elif not re.match(regexes['value'], value):
            value_error = {str(value): "Label value does not match the regex"}

        if key_error:
            errors.append(key_error)
        if value_error:
            errors.append(value_error)

    if errors:
        raise ValidationError({'messages': errors})

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    key_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    value_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')

    messages = []
    for key, value in labels.items():
        if isinstance(value, list):
            for val in value:
                if not value_regex.match(val):
                    messages.append({str(val): 'expected string or bytes-like object'})
        else:
            if not key_regex.match(key):
                messages.append({key: "Label key '{}' does not match the regex {}".format(key, key_regex)})
            if not value_regex.match(value):
                messages.append({str(value): 'expected string or bytes-like object'})

    if messages:
        raise ValidationError(messages)

