                if field not in observer_schema:
                    continue
                if isinstance(value, list):
                    if len(value) == 1:
                        update_last_applied_manifest_list_from_resp(
                            last_applied_manifest.get(field, []),
                            observer_schema[field],
                            value[0]
                        )
                    else:
                        raise ValueError("Unsupported list format in response")
