        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if len(last_applied_manifest) != len(observer_schema) or len(last_applied_manifest) != len(response):
        raise ValueError("The length of last_applied_manifest, observer_schema, and response must be the same")

    for i, (schema, resp) in enumerate(zip(observer_schema, response)):
        if isinstance(schema, dict) and isinstance(resp, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], schema, resp)
        elif isinstance(schema, list) and isinstance(resp, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i], schema, resp)
