def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schema = {}
    for resource in app.spec.manifest:
        resource_type = resource['apiVersion'] + '/' + resource['kind']
        resource_schema = {
            "type": "object",
            "properties": {
                "status": {
                    "type": "object",
                    "properties": {
                        "conditions": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "type": {"type": "string"},
                                    "status": {"type": "string"},
                                    "reason": {"type": "string"},
                                    "message": {"type": "string"},
                                    "lastUpdateTime": {"type": "string"}
                                },
                                "required": ["type", "status", "lastUpdateTime"]
                            }
                        },
                        "phase": {"type": "string"}
                    },
                    "required": ["conditions", "phase"]
                }
            }
        }
        default_schema[resource_type] = resource_schema

    return default_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    observer_schema = {}
    for resource in app.spec.manifest:
        if 'observer_schema' in resource:
            continue
        resource_type = resource['apiVersion'].split('/')[1]
        resource_name = resource['kind']
        observer_schema[resource_name] = {
            'version': resource['apiVersion'],
            'resource': resource_type,
            'observe': ['status', 'spec']
        }
    return observer_schema

