def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise ValueError("Invalid sql type. Expected str or bytes.")

    if not isinstance(params, (dict, tuple, list)):
        raise ValueError("Invalid params type. Expected dict, tuple, or list.")

    if isinstance(params, dict):
        params_are_named = all(isinstance(k, (str, bytes)) for k in params.keys())
        params_are_ordinal = all(isinstance(k, (int,)) for k in params.keys())
        if not (params_are_named or params_are_ordinal):
            raise ValueError("Invalid params. Keys must be either all strings/bytes or all integers.")
    elif isinstance(params, (tuple, list)):
        if not all(isinstance(k, (int,)) for k in params):
            raise ValueError("Invalid params. Elements must be integers.")

    out_params: Union[Dict[Union[str, int], Any], Sequence[Any]]
    if self.in_style == 'named':
        if not isinstance(params, dict):
            raise ValueError("Params must be a dictionary when using named parameters.")
        out_params = {f'out_{k}': v for k, v in params.items()}
    elif self.in_style == 'ordinal':
        if not isinstance(params, (list, tuple)):
            raise ValueError("Params must be a list or tuple when using ordinal parameters.")
        out_params = [f'out_{i+1}' for i in range(len(params))]

    out_sql = sql
    if isinstance(out_sql, str):
        out_sql = out_sql.replace('%s', '?')
    elif isinstance(out_sql, bytes):
        out_sql = bytes(out_sql.replace(b'%s', b'?'), 'utf-8')

    return out_sql, out_params

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
		:class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")

    if isinstance(params, dict):
        if self.SQLParams.in_style == 'named':
            out_style_params = {f':{k}': v for k, v in params.items()}
        else:
            raise ValueError("params must be a sequence for ordinal parameter style")
    elif isinstance(params, (list, tuple)):
        if self.SQLParams.in_style == 'ordinal':
            out_style_params = list(params)
        else:
            raise ValueError("params must be a mapping for named parameter style")
    else:
        raise TypeError("params must be a dict or a sequence")

    formatted_sql = sql % tuple(out_style_params.values())
    return formatted_sql, out_style_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if isinstance(sql, bytes):
        out_style_sql = sql.decode()
    else:
        out_style_sql = sql

    formatted_params = []
    for params in many_params:
        if isinstance(params, dict):
            formatted_params.append({f'out_{key}': value for key, value in params.items()})
        else:
            formatted_params.append([f'out_{value}' for value in params])

    return out_style_sql, formatted_params

