def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    if not manifest_files or not digests_used:
        return False

    for manifest_file in manifest_files:
        if manifest_file not in self.manifest_files:
            return False

    for digest in digests_used:
        if digest not in self.digests or self.digests[digest] == 0:
            return False

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    for manifest_file in manifest_files:
        if manifest_file not in digests_used:
            raise ValueError(f"Manifest file {manifest_file} is present but not used.")

    for digest in digests_used:
        if digest not in self.digests:
            raise ValueError(f"Digest {digest} is used but not present in stored digests.")

    for manifest_file, expected_digest in digests_used.items():
        if self.digests[manifest_file] != expected_digest:
            raise ValueError(f"Digest mismatch for manifest file {manifest_file}: expected {expected_digest}, got {self.digests[manifest_file]}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Check if manifest_files is a list
    if not isinstance(manifest_files, list):
        raise ValueError("manifest_files must be a list of file paths")

    # Check if digests_used is a set
    if not isinstance(digests_used, set):
        raise ValueError("digests_used must be a set of digests")

    # Initialize a set to keep track of missing digests
    missing_digests = digests_used.copy()

    # Iterate over each manifest file
    for manifest_file in manifest_files:
        try:
            # Open the manifest file and read its contents
            with open(manifest_file, 'r') as file:
                lines = file.readlines()

            # Check each line in the manifest file
            for line in lines:
                # Assume digests are in a specific format and extract them
                digest_index = line.find('digest=')
                if digest_index != -1:
                    start_index = digest_index + len('digest=')
                    end_index = line.find(',', start_index)
                    if end_index == -1:
                        end_index = len(line)
                    extracted_digest = line[start_index:end_index].strip().strip('"')

                    # Check if the extracted digest is in the digests_used set
                    if extracted_digest in missing_digests:
                        missing_digests.remove(extracted_digest)

        except FileNotFoundError:
            print(f"Manifest file not found: {manifest_file}")
        except Exception as e:
            print(f"An error occurred while processing {manifest_file}: {e}")

    # Check if there are any missing digests
    if missing_digests:
        raise ValueError(f"Missing digests: {missing_digests}")

    # If all digests are present and used, return True
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing_digests = set()
    unused_digests = digests_used.copy()

    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as file:
            manifest_content = file.read()
            for digest in manifest_content.split():
                if digest in unused_digests:
                    unused_digests.remove(digest)
                else:
                    missing_digests.add(digest)

    if missing_digests:
        raise ValueError(f"Missing digests: {', '.join(missing_digests)}")

    if unused_digests:
        raise ValueError(f"Unused digests: {', '.join(unused_digests)}")

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Input 'prior' must be an InventoryValidator object")

    if self.inventory_version != prior.inventory_version - 1:
        raise ValueError("Inventory version mismatch")

    if self.inventory_state != 'prior':
        raise ValueError("Current inventory state must be 'prior'")

    if prior.inventory_state != 'current':
        raise ValueError("Given prior state must be 'current'")

    for key in self.inventory.keys():
        if key not in prior.inventory:
            raise ValueError(f"Key '{key}' not found in prior inventory")

        if not isinstance(self.inventory[key], type(prior.inventory[key])):
            raise ValueError(f"Type mismatch for key '{key}': expected {type(prior.inventory[key])}, got {type(self.inventory[key])}")

        if self.inventory[key] != prior.inventory[key]:
            raise ValueError(f"Mismatched value for key '{key}': expected {prior.inventory[key]}, got {self.inventory[key]}")

    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Input 'prior' must be an instance of InventoryValidator")

    if set(self.variables) != set(prior.variables):
        raise ValueError("The set of variables in the current inventory and the prior do not match")

    if not all(item in prior.volumes for item in self.volumes):
        raise ValueError("Some volumes in the current inventory do not exist in the prior")

    if not all(item in prior.capacities for item in self.capacities):
        raise ValueError("Some capacities in the current inventory do not exist in the prior")

    if not all(item in prior.timescales for item in self.timescales):
        raise ValueError("Some timescales in the current inventory do not exist in the prior")

    if not all(item in prior.parameters for item in self.parameters):
        raise ValueError("Some parameters in the current inventory do not exist in the prior")

    for var, value in self.__dict__.items():
        if var in prior.__dict__:
            if not np.array_equal(value, prior.__dict__[var]):
                raise ValueError(f"The value for variable '{var}' has changed between the current inventory and the prior")

