def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    datas = {}
    try:
        if not os.path.isdir(folder):
            logger.warning(f'Warning - [{folder} does not exist]')
            return datas

        for root, _, files in os.walk(folder):
            for f in files:
                if f.endswith('.xml'):
                    xml_file_path = os.path.join(root, f)
                    base_name = f[:-4]
                    if base_name not in datas:
                        datas[base_name] = []
                    datas[base_name].append(xml_file_path)
    except Exception as e:
        logger.error(f'Error exploring folder {folder}: {e}')
    return datas

