def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    valid_formats = {
        'suppl': r'(?i)suppl(?:\.?)\s*(?:\d+)?',
        'spe': r'(?i)spe(?:\.?)\s*(?:\d+)?',
        'number': r'\d+'
    }

    result = {'number': None, 'suppl': None}

    for tag, pattern in valid_formats.items():
        match = re.search(pattern, issue)
        if match:
            value = match.group().strip().upper()
            if tag == 'number':
                result['number'] = int(value)
            else:
                result['suppl'] = value

    return result

import re

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extracts the number and supplement from the content of <issue>xxxx</issue>.

    :param issue: The content of the <issue> tag.
    :returns: A tuple containing the extracted number and supplement, or (None, None) if no match is found.
    """
    # Regular expression to match the number and supplement patterns
    pattern = r'(\d+)(\s*suppl[s\.\s]*(\d+)?)?'
    match = re.match(pattern, issue, re.IGNORECASE)

    if match:
        number = match.group(1)
        supplement = match.group(3)
        if supplement and supplement.lower().startswith('spe'):
            supplement = 'spe'
        return (number, supplement)
    else:
        return (None, None)

