def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr == 'A & (A | B)':
            result.append('A')
        elif expr == 'A | (A & B)':
            result.append('A')
        elif expr == 'A & (~A | B)':
            result.append('A & B')
        elif expr == 'A | (~A & B)':
            result.append('A | B')
        else:
            result.append(expr)
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        # Handle absorption laws
        if isinstance(arg, tuple) and len(arg) == 3:
            operator, left, right = arg
            if operator == '&':
                if left == right:
                    new_args.append(left)
                elif (isinstance(right, tuple) and right[0] == '|'):
                    if right[1] == left or right[2] == left:
                        new_args.append(left)
            elif operator == '|':
                if left == right:
                    new_args.append(left)
                elif (isinstance(right, tuple) and right[0] == '&'):
                    if right[1] == left or right[2] == left:
                        new_args.append(left)
        # Handle negative absorption laws
        elif isinstance(arg, tuple) and len(arg) == 4:
            operator, neg_operator, left, right = arg
            if (operator == '&' and neg_operator == '&'):
                if left == right:
                    new_args.append(right)
            elif (operator == '|' and neg_operator == '|'):
                if left == right:
                    new_args.append(right)
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption(expr):
        if expr[0] == '&':
            if expr[2] == '|':
                return expr[0], expr[1]  # A & (A | B) = A
            elif expr[2] == '&':
                return expr[0], expr[1]  # A & (A & B) = A
        elif expr[0] == '|':
            if expr[2] == '|':
                return expr[0], expr[1]  # A | (A | B) = A
            elif expr[2] == '&':
                return expr[0], expr[1]  # A | (A & B) = A
        elif expr[0] == '&':
            if expr[2] == '~':
                if expr[3] == '|':
                    return expr[0], expr[4]  # A & (~A | B) = A & B
                elif expr[3] == '&':
                    return expr[0], expr[4]  # A & (~A & B) = A & B
        elif expr[0] == '|':
            if expr[2] == '~':
                if expr[3] == '|':
                    return expr[0], expr[4]  # A | (~A | B) = A | B
                elif expr[3] == '&':
                    return expr[0], expr[4]  # A | (~A & B) = A | B
        return expr

    return [apply_absorption(arg) for arg in args]

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        if not hasattr(self, '_handlers'):
            self._handlers = {}
        if hook not in self._handlers:
            self._handlers[hook] = []
        self._handlers[hook].append(func)
        return func
    return decorator

