def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    for command, arg in zip(commands, args):
        try:
            if hide_stderr:
                subprocess.check_call([command] + arg, cwd=cwd, env=env, stderr=subprocess.STDOUT)
            else:
                subprocess.check_call([command] + arg, cwd=cwd, env=env)
            if verbose:
                print(f"Command '{command}' with args '{arg}' executed successfully.")
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Failed to execute command '{command}' with args '{arg}': {e.output.decode()}")
