def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_args = {}
    remaining_args = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        try:
            parsed_result, unparsed_remaining = subparser.parse_known_args(args=remaining_args)
            if unparsed_remaining:
                remaining_args = unparsed_remaining
            else:
                remaining_args = []
            parsed_args[subparser_name] = parsed_result
        except SystemExit:
            # ignore SystemExit raised by argparse for unknown options if any
            pass

    return parsed_args, remaining_args

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    import argparse
    from collections import namedtuple

    Parser = namedtuple('Parser', ['main', 'subparsers'])

    try:
        main_parser = argparse.ArgumentParser(description='My Application')
        subparsers = main_parser.add_subparsers(dest='command')
    except Exception as e:
        raise Exception(f"Failed to create main parser and subparsers: {e}")

    def add_subparser(name, help_text):
        try:
            subparser = subparsers.add_parser(name, help=help_text)
            return subparser
        except Exception as e:
            raise Exception(f"Failed to add subparser {name}: {e}")

    try:
        parser_some_command = add_subparser('some_command', 'Performs some action')
        parser_another_command = add_subparser('another_command', 'Does another action')
    except Exception as e:
        raise Exception(f"Failed to add subparsers: {e}")

    return Parser(main=main_parser, subparsers=subparsers)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size_parts = size[:-1].upper(), size[-1].upper()
    try:
        num = float(size_parts[0])
    except ValueError:
        raise ValueError("Invalid number in size string")

    if size_parts[1] == 'B':
        return int(num)
    elif size_parts[1] == 'K':
        return int(num * 1024)
    elif size_parts[1] == 'M':
        return int(num * 1024 ** 2)
    elif size_parts[1] == 'G':
        return int(num * 1024 ** 3)
    elif size_parts[1] == 'T':
        return int(num * 1024 ** 4)
    elif size_parts[1] == 'P':
        return int(num * 1024 ** 5)
    elif size_parts[1] == 'E':
        return int(num * 1024 ** 6)
    elif size_parts[1] == 'Z':
        return int(num * 1024 ** 7)
    elif size_parts[1] == 'Y':
        return int(num * 1024 ** 8)
    else:
        raise ValueError("Invalid unit in size string")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.isdigit():
        return int(size)

    units = {'B': 1, 'K': 1024, 'M': 1024**2, 'G': 1024**3, 'T': 1024**4, 'P': 1024**5, 'E': 1024**6, 'Z': 1024**7, 'Y': 1024**8}

    if size[-1] in units:
        try:
            return int(float(size[:-1]) * units[size[-1]])
        except ValueError:
            raise ValueError("Invalid size format")
    else:
        raise ValueError("Unknown unit")

