import re

POSIX_SPLIT = re.compile(r'("\\")?([^\s\\"]+)|("[^"]*")')
WINDOWS_SPLIT = re.compile(r'("\\")?([^\s\\"]+)|(\\")|(("[^"]*"))')

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:
        return helper(s, POSIX_SPLIT)
    elif platform == 0:
        return helper(s, WINDOWS_SPLIT)
    else:
        raise ValueError("Unsupported platform")

def helper(s, regex):
    result = []
    for match in regex.finditer(s):
        if match.group(1) is None:
            result.append(match.group(2))
        elif match.group(3) is not None:
            result.append(match.group(3).strip('"'))
        elif match.group(4) is not None:
            result.append(match.group(4).strip('"'))
    return result

