def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f'Archive not found: {archive_path}')

    if not os.path.isabs(archive_path):
        archive_path = os.path.abspath(archive_path)

    if isinstance(tmp_path, PosixPath):
        tmp_path = str(tmp_path)

    if not os.path.exists(tmp_path):
        os.makedirs(tmp_path)

    if not filename:
        tmp_dir = Path(tmp_path) / Path(archive_path).name.replace('.tar.gz', '').replace('.tar.bz2', '')
    else:
        tmp_dir = Path(tmp_path) / filename

    if tmp_dir.exists():
        shutil.rmtree(tmp_dir)

    os.makedirs(tmp_dir)

    if archive_path.endswith('.tar.gz'):
        subprocess.run(['tar', '-xzf', archive_path, '-C', tmp_dir], check=True)
    elif archive_path.endswith('.tar.bz2'):
        subprocess.run(['tar', '-xjf', archive_path, '-C', tmp_dir], check=True)
    elif archive_path.endswith('.zip'):
        subprocess.run(['unzip', archive_path, '-d', tmp_dir], check=True)
    else:
        raise ValueError(f'Unsupported archive type: {archive_path}')

    return f'file://{tmp_dir}'

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    from pathlib import Path

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    if isinstance(tmp_path, PosixPath):
        tmp_path = str(tmp_path)

    if not os.path.exists(tmp_path):
        raise FileNotFoundError(f"Temporary path not found: {tmp_path}")

    if filename is None:
        filename = os.path.basename(archive_path)

    output_path = os.path.join(tmp_path, filename)

    if archive_path.endswith('.tar.gz'):
        subprocess.run(['tar', '-zxvf', archive_path, '-C', tmp_path], check=True)
    elif archive_path.endswith('.tar.bz2'):
        subprocess.run(['tar', '-jxvf', archive_path, '-C', tmp_path], check=True)
    elif archive_path.endswith('.zip'):
        subprocess.run(['unzip', archive_path, '-d', tmp_path], check=True)
    else:
        raise ValueError(f"Unsupported archive type: {archive_path}")

    return f"file://{output_path}"

