import re
from datetime import timedelta

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    unit_map = {
        'seconds': 'seconds',
        'minutes': 'minutes',
        'hours': 'hours',
        'days': 'days',
        'weeks': 'weeks',
        'months': 'days',  # Approximation
        'years': 'days'    # Approximation
    }

    match = re.match(r'(\d+)\s*([a-zA-Z]+)', frequency)
    if match:
        number = int(match.group(1))
        unit = match.group(2).lower()
        if unit in unit_map:
            return timedelta(**{unit_map[unit]: number})
        else:
            raise ValueError(f"Unsupported time unit: {unit}")
    else:
        raise ValueError(f"Invalid frequency string: {frequency}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    if frequency is None or frequency == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")

    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError("Invalid frequency number")

    unit = parts[1].lower()
    if unit not in ["seconds", "minutes", "hours", "days", "weeks", "months", "years"]:
        raise ValueError("Invalid frequency unit")

    if unit == "seconds":
        return datetime.timedelta(seconds=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "months":
        return datetime.timedelta(days=number * 30)  # Approximation for months
    elif unit == "years":
        return datetime.timedelta(days=number * 365)  # Approximation for years

