import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    for cmd in commands:
        for arg in args:
            if verbose:
                print(f"Running command: {' '.join([cmd] + arg)}")

            try:
                if hide_stderr:
                    process = subprocess.Popen([cmd] + arg, cwd=cwd, env=env, stderr=subprocess.DEVNULL, stdout=subprocess.PIPE)
                else:
                    process = subprocess.Popen([cmd] + arg, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)

                output, _ = process.communicate()
                return_code = process.wait()

                if return_code != 0:
                    raise subprocess.CalledProcessError(return_code, ' '.join([cmd] + arg), output)

                if verbose:
                    print(f"Command output: {output.decode('utf-8')}")

                return output

            except FileNotFoundError:
                print(f"Command not found: {cmd}")
            except Exception as e:
                print(f"Error running command: {str(e)}")

    return None

