from rdflib import Graph, URIRef, Literal
from typing import Optional, Set

def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[Set[Literal]] = None
) -> Set[Literal]:
    if roots is None:
        roots = set()

    for s, p, o in graph.triples((None, prop, None)):
        if p != prop:
            continue
        if o not in roots:
            roots.add(o)
        if s not in roots:
            roots.add(s)

    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    visited = set()

    for s, p, o in graph:
        if p == prop and s not in visited:
            roots.discard(s)
            visited.add(s)
            for _, _, p in graph.triples((s, prop, None)):
                roots.discard(p)

    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    child_to_parent = {s: o for s, p, o in graph.triples() if p == prop}

    for node in child_to_parent:
        if node not in child_to_parent.values():
            roots.add(node)

    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    nodes_to_visit = set(graph.subjects()) - roots

    while nodes_to_visit:
        node = nodes_to_visit.pop()
        parents = set(graph.objects(node, prop))

        if not parents:
            roots.add(node)
        else:
            nodes_to_visit.update(parents - roots)

    return roots

