import os
import yaml
import toml

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import logging
    log = logging.getLogger(__name__)

    config_dict = {}
    errors = []

    for filename in config_filenames:
        try:
            if not os.path.exists(filename):
                errors.append(logging.LogRecord('load_configurations', logging.ERROR, None, None, f"File '{filename}' does not exist.", {}, None))
                continue

            with open(filename) as fd:
                raw_config = fd.read()

            if filename.endswith('.toml'):
                config = toml.loads(raw_config)
            elif filename.endswith('.yaml') or filename.endswith('.yml'):
                config = yaml.safe_load(raw_config)
            else:
                errors.append(logging.LogRecord('load_configurations', logging.ERROR, None, None, f"Unsupported file format: '{filename}'", {}, None))
                continue

            if resolve_env:
                import os
                config = {key: os.path.expandvars(value) if isinstance(value, str) else value for key, value in config.items()}

            if overrides:
                config.update(overrides)

            config_dict[filename] = config
        except Exception as e:
            errors.append(logging.LogRecord('load_configurations', logging.ERROR, None, None, f"Failed to load or parse '{filename}': {e}", {}, None))

    return config_dict, errors

import logging
import configparser
import os

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    config_dict = {}
    error_records = []

    for filename in config_filenames:
        try:
            config = configparser.ConfigParser(allow_no_value=True)
            config.read_dict(config.read(filename), source=filename)
        except Exception as e:
            error_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, None, str(e), (), None))
            continue

        if overrides:
            for section, values in overrides.items():
                if not config.has_section(section):
                    config.add_section(section)
                for key, value in values.items():
                    config.set(section, key, value)

        if resolve_env:
            config.resolve()

        config_dict[filename] = config

    return config_dict, error_records

import logging
import toml
import yaml
from typing import Dict, List, Optional, Tuple

def load_configurations(config_filenames: List[str], overrides: Optional[Dict[str, dict]] = None, resolve_env: bool = True) -> Tuple[Dict[str, dict], List[logging.LogRecord]]:
    """Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    parsed_configs = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                raw_config = fd.read()

            if filename.endswith('.toml'):
                config_dict = toml.loads(raw_config)
            elif filename.endswith('.yaml') or filename.endswith('.yml'):
                config_dict = yaml.safe_load(raw_config)
            else:
                raise ValueError(f"Unsupported file type: {filename}")

            if resolve_env:
                config_dict = resolve_environment_variables(config_dict)

            for key, value in overrides.items():
                if key in config_dict:
                    config_dict[key].update(value)

            parsed_configs[filename] = config_dict
        except FileNotFoundError:
            log_record = logging.LogRecord(name='load_configurations', level=logging.WARNING, pathname=__file__, lineno=123, msg=f"Config file not found: {filename}", args=(), exc_info=None)
            log_records.append(log_record)
        except (toml.TomlDecodeError, yaml.YAMLError) as e:
            log_record = logging.LogRecord(name='load_configurations', level=logging.ERROR, pathname=__file__, lineno=123, msg=f"Error parsing {filename}: {e}", args=(), exc_info=None)
            log_records.append(log_record)

    return parsed_configs, log_records

def resolve_environment_variables(config_dict: dict) -> dict:
    """Recursively replace environment variable references in a dictionary with their actual values."""
    for key, value in config_dict.items():
        if isinstance(value, dict):
            resolve_environment_variables(value)
        elif isinstance(value, str):
            config_dict[key] = value.format(**os.environ)
    return config_dict

