import numpy as np

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    elif isinstance(obj, np.ndarray) and obj.dtype == 'S1':
        return obj.view('U').flatten()
    elif isinstance(obj, np.ndarray) and obj.dtype == 'U':
        return obj.view('S').flatten()
    elif isinstance(obj, bytes):
        return obj
    elif isinstance(obj, np.ndarray) and obj.dtype == 'O':
        return np.array([item.encode('utf-8') if isinstance(item, str) else item for item in obj])
    else:
        raise ValueError("Unsupported type for conversion to bytes")

from datetime import datetime, timedelta

class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        if not (0 <= ticks < 86400000000000):
            raise ValueError("Ticks must be within the range 0 <= ticks < 86400000000000")

        seconds = ticks // 1_000_000_000
        microseconds = (ticks % 1_000_000_000) // 1_000

        time_of_day = timedelta(seconds=seconds, microseconds=microseconds)

        if tz is None:
            return time_of_day
        else:
            return (datetime.min + time_of_day).replace(tzinfo=tz)

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")

        handlers = {}
        for version, handler in cls._protocol_handlers.items():
            if protocol_version is None or version == protocol_version:
                handlers[version] = handler

        return handlers

