def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    if not hasattr(candidate, '__implements__'):
        if not tentative:
            raise AttributeError("Candidate does not have __implements__ attribute")
        return False

    if not isinstance(candidate.__implements__, (list, tuple, type(None))):
        if not tentative:
            raise TypeError("Candidate __implements__ attribute is not a list, tuple or None")
        return False

    if iface not in candidate.__implements__ and tentative:
        return False

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        for attr in dir(iface):
            if not attr.startswith('_'):
                if not hasattr(candidate, attr):
                    return False
                iface_attr = getattr(iface, attr)
                candidate_attr = getattr(candidate, attr)
                if not callable(iface_attr):
                    if candidate_attr != iface_attr:
                        return False
                else:
                    if not candidate_attr(*candidate_attr.__annotations__.values()):
                        return False
        return True
    except AttributeError:
        return False

