    for method_name in dir(iface):
        if callable(getattr(iface, method_name)):
            method = getattr(candidate, method_name, None)
            if not method:
                if tentative:
                    continue
                else:
                    raise AttributeError(f'{candidate} does not have the required method {method_name}')
