def parse_xrd(document: str) -> Dict:
    root = ET.fromstring(document)
    d = {}
    for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd/1.0}Link'):
        rel = link.get('rel')
        if rel in d:
            if isinstance(d[rel], list):
                d[rel].append(link.get('href'))
            else:
                d[rel] = [d[rel], link.get('href')]
        else:
            d[rel] = link.get('href')
    return d

