def dict_insert(dic, val, key, *keys):
    """Insert a value into a nested key in a dictionary.

    To insert a value for a nested key, all ancestor keys should be provided as method arguments.

    Example:
      dict_insert({}, 'val', 'key1', 'key2')

    :param dic: The dictionary object to insert the nested key value into.
    :param val: The value to insert into the given dictionary.
    :param key: The first key in the chain of keys that will store the value.
    :param keys: Sub-keys in the keys chain.
    """
    if not keys:
        dic[key] = val
    else:
        if key not in dic:
            dic[key] = {}
        dict_insert(dic[key], val, keys[0], *keys[1:])

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a list of file names from the given directories based on the specified option.

    Args:
        settings_dirs (list): List of directory paths to search for files.
        spec_option (str): The specification option to filter file names.

    Returns:
        list: List of file names that match the specified option.
    """
    file_names = []
    for directory in settings_dirs:
        try:
            for root, _, files in os.walk(directory):
                for file in files:
                    if file.endswith(spec_option):
                        file_names.append(os.path.join(root, file))
        except OSError:
            continue
    return sorted(file_names)

