def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    for var in extra_vars:
        if isinstance(var, dict):
            vars_dict.update(var)
        elif isinstance(var, list):
            for item in var:
                if isinstance(item, dict):
                    vars_dict.update(item)
                elif item not in vars_dict:
                    vars_dict[item] = True

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend vars_dict with extra-vars

    Args:
        vars_dict (dict): Dictionary to merge extra-vars into
        extra_vars (list, optional): List of extra-vars to merge. Defaults to None.

    Returns:
        dict: Merged dictionary

    Examples:
        >>> vars_dict = {"var1": "val1", "var2": "val2"}
        >>> extra_vars = [{"var1": "val111"}, {"var3": "val3"}]
        >>> merge_extra_vars(vars_dict, extra_vars)
        {'var1': 'val111', 'var2': 'val2', 'var3': 'val3'}
    """
    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, list):
        raise ValueError("extra_vars should be a list")

    for extra_var in extra_vars:
        if not isinstance(extra_var, dict):
            raise ValueError("Each element in extra_vars should be a dictionary")

    for extra_var in extra_vars:
        vars_dict.update(extra_var)

    return vars_dict

