def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    # Construct the command list
    command = ["ansible-playbook"]
    if verbose:
        if verbose == 1:
            command.append("-v")
        elif verbose == 2:
            command.append("-vv")
        elif verbose == 3:
            command.append("-vvv")
        elif verbose == 4:
            command.append("-vvvv")
        elif verbose == 5:
            command.append("-vvvvv")

    if extra_vars:
        for key, value in extra_vars.items():
            command.extend(["--extra-vars", f"{key}={value}"])

    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, list):
                for item in value:
                    command.extend([key, item])
            else:
                command.extend([key, value])

    command.append(playbook_path)

    # Execute the command
    import subprocess
    logger = ir_plugin.logger
    logger.debug("ExecutingAnsible call `%s`", " ".join(command))
    p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = p.communicate()

    if p.returncode != 0:
        logger.error("Ansible reported an error when executing playbook %s: %s", playbook_path, stderr.decode())
        raise RuntimeError(f"Ansible reported an error when executing playbook {playbook_path}: {stderr.decode()}")

    return stdout.decode()

