def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flatten_dict = {}
    spec_file_path = os.path.join(plugin_dir, 'plugin.spec')

    if not os.path.exists(spec_file_path):
        raise FileNotFoundError(f"Plugin spec file not found at {spec_file_path}")

    with open(spec_file_path, 'r') as file:
        spec_data = json.load(file)

    def flatten(data, parent_key='', sep='_'):
        for k, v in data.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                flatten(v, new_key, sep)
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    flatten({str(i): item}, new_key, sep)
            else:
                flatten_dict[new_key] = v

    flatten(spec_data)
    return flatten_dict

def inject_config(self, config_path=None):
    """Set the environment variable for config path, if it is undefined."""
    if config_path is None:
        return

    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = str(config_path)

