def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param subparser: the subparser object to extend.
    """
    if not root_subparsers:
        raise ValueError("root_subparsers must be provided")

    for subcommand, options in self.cli_commands.items():
        subparser.add_parser(subcommand, **options)
